use error as core
struct node:
    value: i32
func node_positive(const value: node) -> bool:
    return value.value > 0
func finding<t>(const items: [t], predicate: func(const t) -> bool) -> result<t, core.error>:
    for item in items:
        if predicate(item):
            return Ok(item)
    return Err(core.error(message = "not found"))
func copied<k,v>(const items: {k:v}) -> {k:v}:
    for first_value, first_key in items:
        var output = {first_key: first_value}
        for value, key in items:
            output[key] = value
        return output
    var empty: {k:v} = {}
    return empty
func keys_of<k,v>(const items: {k:v}) -> [k]:
    for first_value, first_key in items:
        var output = [first_key]
        output.clear()
        for value, key in items:
            output.push(key)
        return output
    var empty: [k] = []
    return empty
func values_of<k,v>(const items: {k:v}) -> [v]:
    for first_value, first_key in items:
        var output = [first_value]
        output.clear()
        for value, key in items:
            output.push(value)
        return output
    var empty: [v] = []
    return empty
func mapping<t,u>(const items: [t], transform: func(const t) -> u) -> [u]:
    var output: [u] = []
    for item in items:
        output.push(transform(item))
    return output
func fresh_nullable(const value: node) -> node?:
    if value.value > 0:
        return node(value = value.value)
    return null
func pair(const value: node) -> [i32,2]:
    return [value.value, value.value]
func make_result(const value: node) -> result<node, string>:
    return Ok(node(value = value.value))
func make_callback(const value: node) -> func() -> i32:
    var held = value.value
    return func() -> i32:
        return held
func main():
    var data = [node(value = 7)]
    if finding(data, node_positive) is Ok(var found):
        print(found.value)

