struct node:
    value: i32
func identity(const value: node) -> node:
    return value
func fresh(const value: node) -> node:
    return node(value = value.value)
func number(const value: node) -> i32:
    return value.value
func positive(const value: i32) -> bool:
    return value > 0
func mapping<t,u>(const items: [t], transform: func(const t) -> u) -> [u]:
    var output: [u] = []
    for item in items:
        output.push(transform(item))
    return output
func copying<t>(const items: [t]) -> [t]:
    var output: [t] = []
    for item in items:
        output.push(item)
    return output
func index_of<c,t>(const items: c, predicate: func(const t) -> bool) -> i64:
    for item, index in items:
        if predicate(item):
            return index
    return -1
func filtered<t>(const items: [t], predicate: func(const t) -> bool) -> [t]:
    var output = items[0..<0]
    for item in items:
        if predicate(item):
            output.push(item)
    return output
func node_positive(const value: node) -> bool:
    return value.value > 0
func folded<t,u>(const items: [t], initial: u, combine: func(u, const t) -> u) -> u:
    var total = initial
    for item in items:
